shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/parser.y b/src/parser.y
--- a/src/parser.y
+++ b/src/parser.y
@@ -710,6 +710,12 @@ Term '[' ']' '?' {
 Term '[' ']' %prec NONOPT {
   $$ = block_join($1, gen_op_simple(EACH));
 } |
+Term '.' '[' ']' '?' {
+  $$ = block_join($1, gen_op_simple(EACH_OPT));
+} |
+Term '.' '[' ']' %prec NONOPT {
+  $$ = block_join($1, gen_op_simple(EACH));
+} |
 Term '[' Exp ':' Exp ']' '?' {
   $$ = gen_slice_index($1, $3, $5, INDEX_OPT);
 } |
@@ -728,6 +734,24 @@ Term '[' Exp ':' ']' %prec NONOPT {
 Term '[' ':' Exp ']' %prec NONOPT {
   $$ = gen_slice_index($1, gen_const(jv_null()), $4, INDEX);
 } |
+Term '.' '[' Exp ':' Exp ']' '?' {
+  $$ = gen_slice_index($1, $4, $6, INDEX_OPT);
+} |
+Term '.' '[' Exp ':' ']' '?' {
+  $$ = gen_slice_index($1, $4, gen_const(jv_null()), INDEX_OPT);
+} |
+Term '.' '[' ':' Exp ']' '?' {
+  $$ = gen_slice_index($1, gen_const(jv_null()), $5, INDEX_OPT);
+} |
+Term '.' '[' Exp ':' Exp ']' %prec NONOPT {
+  $$ = gen_slice_index($1, $4, $6, INDEX);
+} |
+Term '.' '[' Exp ':' ']' %prec NONOPT {
+  $$ = gen_slice_index($1, $4, gen_const(jv_null()), INDEX);
+} |
+Term '.' '[' ':' Exp ']' %prec NONOPT {
+  $$ = gen_slice_index($1, gen_const(jv_null()), $5, INDEX);
+} |
 LITERAL {
   $$ = gen_const($1);
 } |
diff --git a/docs/content/manual/manual.yml b/docs/content/manual/manual.yml
--- a/docs/content/manual/manual.yml
+++ b/docs/content/manual/manual.yml
@@ -407,6 +407,16 @@ sections:
           `.['"foo"']` (`.foo` above is a shorthand version of this, but
           only for identifier-like strings).

+          Bracket indexes can be chained as `.['"foo"'].['"bar"']` or
+          `.['"foo"']['"bar"']`, and mixed with identifier indexes, as in
+          `.foo.['"bar"']`. The separating dot is also optional before
+          array indexes, slices, and iterators, as in `.foo.[0]`,
+          `.foo.[1:3]`, and `.foo.[]`.
+
+        examples:
+          - program: '.['"foo"'].['"bar"']'
+            input: '{"foo": {"bar": 42}}'
+            output: [42]
+
       - title: "Array Index: `.[<number>]`"
         body: |
PATCH

cd /testbed && git apply --recount <<'PATCH'
diff --git a/src/parser.y b/src/parser.y
--- a/src/parser.y
+++ b/src/parser.y
@@ -710,6 +710,12 @@ Term '[' ']' '?' {
 Term '[' ']' %prec NONOPT {
   $$ = block_join($1, gen_op_simple(EACH));
 } |
+Term '.' '[' ']' '?' {
+  $$ = block_join($1, gen_op_simple(EACH_OPT));
+} |
+Term '.' '[' ']' %prec NONOPT {
+  $$ = block_join($1, gen_op_simple(EACH));
+} |
 Term '[' Exp ':' Exp ']' '?' {
   $$ = gen_slice_index($1, $3, $5, INDEX_OPT);
 } |
@@ -728,6 +734,24 @@ Term '[' Exp ':' ']' %prec NONOPT {
 Term '[' ':' Exp ']' %prec NONOPT {
   $$ = gen_slice_index($1, gen_const(jv_null()), $4, INDEX);
 } |
+Term '.' '[' Exp ':' Exp ']' '?' {
+  $$ = gen_slice_index($1, $4, $6, INDEX_OPT);
+} |
+Term '.' '[' Exp ':' ']' '?' {
+  $$ = gen_slice_index($1, $4, gen_const(jv_null()), INDEX_OPT);
+} |
+Term '.' '[' ':' Exp ']' '?' {
+  $$ = gen_slice_index($1, gen_const(jv_null()), $5, INDEX_OPT);
+} |
+Term '.' '[' Exp ':' Exp ']' %prec NONOPT {
+  $$ = gen_slice_index($1, $4, $6, INDEX);
+} |
+Term '.' '[' Exp ':' ']' %prec NONOPT {
+  $$ = gen_slice_index($1, $4, gen_const(jv_null()), INDEX);
+} |
+Term '.' '[' ':' Exp ']' %prec NONOPT {
+  $$ = gen_slice_index($1, gen_const(jv_null()), $5, INDEX);
+} |
 LITERAL {
   $$ = gen_const($1);
 } |
diff --git a/docs/content/manual/manual.yml b/docs/content/manual/manual.yml
--- a/docs/content/manual/manual.yml
+++ b/docs/content/manual/manual.yml
@@ -407,6 +407,16 @@ sections:
           `.["foo"]` (`.foo` above is a shorthand version of this, but
           only for identifier-like strings).

+          Bracket indexes can be chained as `.["foo"].["bar"]` or
+          `.["foo"]["bar"]`, and mixed with identifier indexes, as in
+          `.foo.["bar"]`. The separating dot is also optional before
+          array indexes, slices, and iterators, as in `.foo.[0]`,
+          `.foo.[1:3]`, and `.foo.[]`.
+
+        examples:
+          - program: '.["foo"].["bar"]'
+            input: '{"foo": {"bar": 42}}'
+            output: [42]
+
       - title: "Array Index: `.[<number>]`"
         body: |
PATCH
make -j4 > /tmp/jq-generic-index-build.log 2>&1 && ./jq --run-tests --skip 28 --take 17 tests/jq.test > /tmp/jq-generic-index-targeted.log 2>&1; result=$?; tail -35 /tmp/jq-generic-index-build.log; if [ -f /tmp/jq-generic-index-targeted.log ]; then tail -25 /tmp/jq-generic-index-targeted.log; fi; exit "$result"

